import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { blogDir, checkPosts, publishedFiles, scanPosts } from "../../features/blog/scan.ts";
import { homeFiles } from "../../features/home/scan.ts";
import type { DocsConfig } from "../../config/index.ts";

/** Generated files live here (gitignored). React Router's `appDirectory` points at `.consify/app`. */
export const generatedDir = ".consify";
export const appDirectory = `${generatedDir}/app`;

const header = "// Generated by consify. Do not edit, do not commit.";

/** Source of `.consify/instance.ts`: the content macro must live in the project (it is compiled statically). */
export function renderInstance(): string {
  return `${header}
// @ts-nocheck: the project does not depend on fumadocs-mdx, so its macro has no types here. The
// type of \`consify\` seen by route modules is declared by "consify:instance" instead.
import { componentsFromGlob, createConsify, slotsFromGlob } from "consify";
import { defineDocs } from "fumadocs-mdx/macro";
import config from "../docs.config.ts";

const docs = defineDocs({
  dir: "content/docs",
  docs: {
    // Only frontmatter is bundled upfront, page content is loaded on demand.
    async: true,
    // Needed for llms.txt / llms-full.txt.
    postprocess: { includeProcessedMarkdown: true },
  },
});

// custom/components/Foo.tsx becomes <Foo /> in every .mdx file.
const custom = import.meta.glob("/custom/components/*.{tsx,jsx}", { eager: true });
// custom/home.tsx, custom/header.tsx and custom/footer.tsx replace parts of the site.
const slots = import.meta.glob("/custom/{home,header,footer}.{tsx,jsx}", { eager: true });

export const consify = createConsify(config, docs, componentsFromGlob(custom), slotsFromGlob(slots));
`;
}

export function renderRoot(hasCustomCss: boolean): string {
  return `${header}
import "consify/theme.css";
${hasCustomCss ? 'import "../../custom/theme.css";\n' : ""}export { default, ErrorBoundary, Layout } from "consify/react-router/root";
`;
}

/**
 * Source of `.consify/blog.ts`. Only the published posts are listed in `files`, so a draft or a
 * post dated in the future is never compiled: it cannot reach the browser or the build output.
 */
export function renderBlog(files: readonly string[] | undefined): string {
  if (files === undefined) {
    return `${header}\nexport const blog = null;\n`;
  }
  const collection =
    files.length === 0
      ? "{ entries: [], get: () => undefined }"
      : `defineCollections({
  type: "doc",
  dir: "content/blog",
  // Only published posts (no drafts, no future dates), read when the site starts.
  files: ${JSON.stringify(files)},
  async: true,
  schema: postFrontmatterSchema,
  postprocess: { includeProcessedMarkdown: true },
})`;
  return `${header}
// @ts-nocheck: the project does not depend on fumadocs-mdx, so its macro has no types here.
import { createBlog, postFrontmatterSchema } from "consify";
import { defineCollections } from "fumadocs-mdx/macro";
import config from "../docs.config.ts";

const posts = ${collection};

export const blog = createBlog(config, posts);
`;
}

/** Source of `.consify/home.ts`: the home page written in MDX, or `null` when there is none. */
export function renderHome(files: readonly string[]): string {
  if (files.length === 0) return `${header}\nexport const home = null;\n`;
  return `${header}
// @ts-nocheck: the project does not depend on fumadocs-mdx, so its macro has no types here.
import { createHome, homeFrontmatterSchema } from "consify";
import { defineCollections } from "fumadocs-mdx/macro";
import config from "../docs.config.ts";

const pages = defineCollections({
  type: "doc",
  dir: "content",
  files: ${JSON.stringify(files)},
  async: true,
  schema: homeFrontmatterSchema,
});

export const home = createHome(config, pages);
`;
}

export function renderRoutes(): string {
  return `${header}
export { default } from "consify/react-router/routes";
`;
}

/** Published post files for `.consify/blog.ts`, or `undefined` when the blog is not enabled. */
function blogFiles(cwd: string, config: Readonly<DocsConfig> | undefined): string[] | undefined {
  if (!config?.blog) return undefined;
  const posts = scanPosts(cwd, config.i18n.languages);
  const problems = checkPosts(posts, {
    categories: config.blog.categories.map((c) => c.id),
    authors: Object.keys(config.blog.authors),
  });
  if (problems.length > 0)
    throw new Error(`Invalid blog posts:\n${problems.map((p) => `  - ${p}`).join("\n")}`);
  return publishedFiles(posts).map((post) => post.path);
}

function writeIfChanged(path: string, content: string): void {
  mkdirSync(dirname(path), { recursive: true });
  if (existsSync(path) && readFileSync(path, "utf8") === content) return;
  writeFileSync(path, content);
}

/**
 * Writes the thin files React Router needs into `.consify/`, so a project keeps only
 * `docs.config.ts`, `vite.config.ts` and `react-router.config.ts`. Safe to call repeatedly.
 */
export function scaffold(cwd: string = process.cwd(), config?: Readonly<DocsConfig>): void {
  const hasCustomCss = existsSync(join(cwd, "custom/theme.css"));
  writeIfChanged(join(cwd, generatedDir, "instance.ts"), renderInstance());
  writeIfChanged(join(cwd, appDirectory, "root.tsx"), renderRoot(hasCustomCss));
  writeIfChanged(join(cwd, appDirectory, "routes.ts"), renderRoutes());
  writeIfChanged(join(cwd, generatedDir, "blog.ts"), renderBlog(blogFiles(cwd, config)));
  writeIfChanged(
    join(cwd, generatedDir, "home.ts"),
    renderHome(config ? homeFiles(cwd, config.i18n.languages) : []),
  );
}
